-- Gerado por scripts/tmdb_catalog.py — cópias, comprovantes e programação de demonstração (após seed_dev.sql).
INSERT INTO copies (film_id, code, patrimonio, condition, status) SELECT f.id, f.internal_code || '-' || g, 'PAT-' || f.internal_code || '-' || g, 'good', 'available' FROM films f CROSS JOIN generate_series(1, 3) g WHERE f.internal_code LIKE 'VT-%' AND g <= 1 + (f.id % 3) AND NOT EXISTS (SELECT 1 FROM copies c WHERE c.film_id = f.id) ON CONFLICT (code) DO NOTHING;
UPDATE events SET description = replace(description, ' [demo]', '') WHERE description LIKE '%[demo]%';
INSERT INTO events (title, event_type, film_id, room_id, location, starts_at, ends_at, slots, enrolled, description, certificate, status) SELECT v.kind || ': ' || f.title, 'session', f.id, 3, 'Mini Auditório', s.starts_at, s.starts_at + make_interval(mins => COALESCE(NULLIF(regexp_replace(f.duration, '\D', '', 'g'), '')::int, 120) + 30), 80, v.enrolled, CASE WHEN v.kind = 'Cineclube' THEN 'Exibição seguida de debate.' ELSE 'Sessão do acervo.' END, v.kind = 'Cineclube', 'published' FROM (VALUES ('VT-0007', 0, '14:00', 'Sessão', 12), ('VT-0013', 0, '19:00', 'Cineclube', 80), ('VT-0025', 1, '14:00', 'Sessão', 34), ('VT-0030', 1, '19:00', 'Sessão', 5), ('VT-0022', 2, '14:00', 'Sessão', 61), ('VT-0008', 2, '19:00', 'Cineclube', 80), ('VT-0027', 3, '14:00', 'Sessão', 20), ('VT-0037', 3, '19:00', 'Sessão', 47), ('VT-0014', 4, '14:00', 'Sessão', 9), ('VT-0034', 4, '19:00', 'Cineclube', 73), ('VT-0018', 5, '14:00', 'Sessão', 30), ('VT-0038', 5, '19:00', 'Sessão', 80), ('VT-0026', 6, '14:00', 'Sessão', 15), ('VT-0021', 6, '19:00', 'Cineclube', 52)) AS v(code, day, hour, kind, enrolled) JOIN films f ON f.internal_code = v.code CROSS JOIN LATERAL (SELECT ((date_trunc('day', NOW() AT TIME ZONE 'America/Fortaleza') + make_interval(days => v.day + 1) + v.hour::time) AT TIME ZONE 'America/Fortaleza') AS starts_at) s WHERE NOT EXISTS (SELECT 1 FROM events WHERE room_id = 3 AND event_type = 'session' AND description IN ('Sessão do acervo.', 'Exibição seguida de debate.'));
